WITH cleaned AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, ROUND(humidity, 1) AS humidity_rounded FROM device_readings WHERE reading_ts > DATE '2025-09-01'), flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '15' MINUTE THEN 1 ELSE 0 END AS session_start_flag FROM cleaned), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, device_code, MIN(reading_ts) AS first_reading_ts, COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END) AS dv_01_count, COUNT_IF(device_code = 'DV-04') AS dv_04_events FROM sessionized GROUP BY 1, 2 ORDER BY dv_04_events DESC NULLS LAST
